import static io.restassured.RestAssured.*;

public class HealthClient {
    public int checkHealth(String baseUrl) {
        return given()
            .when()
            .get(baseUrl + "/health")
            .then()
            .statusCode(200)
            .extract().statusCode();
    }
}

